INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6826700, 1025955, 112739, '<td valign="top">Electricity. Very well done images. The Solar panels are very interesting as they fade into the distance. I love to see all the details in the high tension power lines and the tones and perfect exposure of the light bulb.</td>', 'Electricity. Very well done images. The Solar panels are very interesting as they fade into the distance. I love to see all the details in the high tension power lines and the tones and perfect exposure of the light bulb.', '2012-07-25 00:30:23.000000', NULL, 1),
(6826701, 1026215, 112739, '<td valign="top">King? I don''t know Alessandro. Cool images, but I don''t get the story. Sorry! All I can think is, "Great to be the King". I don''t know anyone who wears a cape and crown and likes to sit alone in the high country. I''m pretty dense sometimes though.</td>', 'King? I don''t know Alessandro. Cool images, but I don''t get the story. Sorry! All I can think is, "Great to be the King". I don''t know anyone who wears a cape and crown and likes to sit alone in the high country. I''m pretty dense sometimes though.', '2012-07-25 00:33:16.000000', NULL, 1),
(6826762, 1026193, 15511, '<td valign="top">Could you enlighten me?</td>', 'Could you enlighten me?', '2012-07-25 01:54:48.000000', NULL, 1),
(6826782, 1026324, 96815, '<td valign="top">Elements! Great shots, I''m interested to know how you did this.</td>', 'Elements! Great shots, I''m interested to know how you did this.', '2012-07-25 02:43:12.000000', NULL, 1),
(6826784, 1026193, 96815, '<td valign="top">One of my highest votes... too bad for me I can''t figure it out! Great set of images but the last one has a slightly different feel than the others-less dramatic. I wish you had kept the style.<br/> <br/>Just came back and got it! Enlighten. Great job! Don''t get the revelation thing, though.</td>', 'One of my highest votes... too bad for me I can''t figure it out! Great set of images but the last one has a slightly different feel than the others-less dramatic. I wish you had kept the style. Just came back and got it! Enlighten. Great job! Don''t get the revelation thing, though.', '2012-07-25 02:47:17.000000', NULL, 1),
(6826786, 1026231, 96815, '<td valign="top">hmmm that pear looks like it''s heart broken. Nice job telling a story using only pears. My guess is something like divorce or seperation</td>', 'hmmm that pear looks like it''s heart broken. Nice job telling a story using only pears. My guess is something like divorce or seperation', '2012-07-25 02:48:11.000000', NULL, 1),
(6826787, 1025620, 96815, '<td valign="top">hunting! Nice shots<br/> <br/>I can''t believe I could recognize a frog.. but is this the same guy that is in image #1021339?</td>', 'hunting! Nice shots I can''t believe I could recognize a frog.. but is this the same guy that is in image #1021339?', '2012-07-25 02:49:27.000000', NULL, 1),
(6826806, 1026234, 22459, '<td valign="top">quit</td>', 'quit', '2012-07-25 05:08:48.000000', NULL, 1),
(6826818, 1026194, 18367, '<td valign="top">If I was a betting man, I would wager good money that this image belongs to <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30982" rel="nofollow" target="_blank">Melethia</a>, particularly when one considers her love of birds.  I have a great appreciation of just how difficult it is to take photos of birds in flight and you have done a great job in this instance Very nicely done, and here is hoping your image does well in the challenge.</td>', 'If I was a betting man, I would wager good money that this image belongs to  Melethia, particularly when one considers her love of birds.  I have a great appreciation of just how difficult it is to take photos of birds in flight and you have done a great job in this instance Very nicely done, and here is hoping your image does well in the challenge.', '2012-07-25 06:41:45.000000', NULL, 1),
